typography.css_variables:
/* Typography System */
:root {
  --font-heading: 'IBM Plex Sans Arabic', 'Inter', sans-serif;
  --font-body: 'IBM Plex Sans Arabic', 'Inter', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --text-display: 4rem;
  --text-h1: 3rem;
  --text-h2: 2.25rem;
  --text-h3: 1.875rem;
  --text-h4: 1.5rem;
  --text-h5: 1.25rem;
  --text-h6: 1.125rem;
  --text-body-lg: 1.125rem;
  --text-body: 1rem;
  --text-body-sm: 0.875rem;
  --text-caption: 0.75rem;
  --text-label: 0.6875rem;

  --leading-display: 1.1;
  --leading-heading: 1.25;
  --leading-subheading: 1.35;
  --leading-body: 1.6;
  --leading-body-compact: 1.4;
  --leading-caption: 1.4;

  --tracking-display: -0.03em;
  --tracking-heading: -0.02em;
  --tracking-subheading: -0.01em;
  --tracking-body: 0em;
  --tracking-label-uppercase: 0.08em;
  --tracking-caption-uppercase: 0.1em;

  --weight-black: 900;
  --weight-extrabold: 800;
  --weight-bold: 700;
  --weight-semibold: 600;
  --weight-medium: 500;
  --weight-regular: 400;
  --weight-light: 300;
}

colors.css_variables:
/* Color System — Light (default) */
:root {
  --color-primary: #2563EB;
  --color-primary-dark: #1D4ED8;
  --color-primary-light: #4A7EEE;
  --color-primary-subtle: #EFF4FF;
  --color-accent: #7C3AED;
  --color-secondary: #1D4ED8;
  --color-accent-subtle: #F4EEFE;
  --color-warning: #D97706;
  --color-error: #DC2626;
  --color-success: #16A34A;
  --color-bg: #F8FAFC;
  --color-bg-subtle: #F1F5F9;
  --color-surface: #FFFFFF;
  --color-border: #E5E7EB;
  --color-border-strong: #CBD5E1;
  --color-text-primary: #071426;
  --color-text-secondary: #475569;
  --color-text-tertiary: #64748B;
  --color-text-inverse: #FFFFFF;
  --color-cyan: #00D1FF;
  --color-violet-2: #B026FF;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --color-primary: #3B82F6;
    --color-primary-dark: #2563EB;
    --color-primary-light: #60A5FA;
    --color-primary-subtle: #122142;
    --color-accent: #8B5CF6;
    --color-secondary: #60A5FA;
    --color-accent-subtle: #1E1533;
    --color-cyan: #00D1FF;
    --color-violet-2: #B026FF;
    --color-warning: #FBBF24;
    --color-error: #F87171;
    --color-success: #4ADE80;
    --color-bg: #071426;
    --color-bg-subtle: #0B1D3A;
    --color-surface: #0B1D3A;
    --color-border: #1E3358;
    --color-border-strong: #2E4570;
    --color-text-primary: #F7FAFC;
    --color-text-secondary: #C3CAD6;
    --color-text-tertiary: #A1A8B3;
    --color-text-inverse: #071426;
  }
}

/* Explicit user override wins regardless of OS preference */
:root[data-theme="dark"] {
  --color-primary: #3B82F6;
  --color-primary-dark: #2563EB;
  --color-primary-light: #60A5FA;
  --color-primary-subtle: #122142;
  --color-accent: #8B5CF6;
  --color-secondary: #60A5FA;
  --color-accent-subtle: #1E1533;
  --color-cyan: #00D1FF;
  --color-violet-2: #B026FF;
  --color-warning: #FBBF24;
  --color-error: #F87171;
  --color-success: #4ADE80;
  --color-bg: #071426;
